                        declare namespace wfs='http://www.opengis.net/wfs/2.0';
declare namespace ows='http://www.opengis.net/ows/1.1';
declare namespace inspire_dls='http://inspire.ec.europa.eu/schemas/inspire_dls/1.0';
declare namespace inspire_common='http://inspire.ec.europa.eu/schemas/common/1.0';

<etfTranslate what="TR.missingElementWithValue"> {
let $languages :=tokenize( '${#supportedLanguageCodes}', ',' )
let $expectedLang :='${#responseLanguageCode}'
for $language in $languages
where not(
   exists(/*:WFS_Capabilities/ows:OperationsMetadata/ows:ExtendedCapabilities/inspire_dls:ExtendedCapabilities[1]/inspire_common:SupportedLanguages/inspire_common:SupportedLanguage[inspire_common:Language=$language])
   or exists(/*:WFS_Capabilities/ows:OperationsMetadata/ows:ExtendedCapabilities/inspire_dls:ExtendedCapabilities[1]/inspire_common:SupportedLanguages/inspire_common:DefaultLanguage[inspire_common:Language=$language])
)
return (<name>Language</name>,<value>{$language}</value>)
}
</etfTranslate>

