   import de.interactive_instruments.xtf.ProjectHelper
   import de.interactive_instruments.xtf.SOAPUI_I
   import com.eviware.soapui.support.XmlHolder
   Assert a = new Assert(messageExchange, context, log, Assert.INSPIRE_DS_NS);


   def capabilities = new XmlSlurper().parseText(a.xml.getXml());

   def scenario = '0';
   if(capabilities.OperationsMetadata.ExtendedCapabilities.ExtendedCapabilities.size() == 0){
      scenario = '3';
      def features = capabilities.FeatureTypeList.FeatureType;
      features.each{feature ->
      if (feature.WGS84BoundingBox.size == 0){
         String[] assertParams = ['elementName', 'WGS84BoundingBox', 'scenario', scenario];
         throw new TranslatableAssertionError('TR.manual.checkContent', assertParams);
         }
      }
   }
   else if(capabilities.OperationsMetadata.ExtendedCapabilities.ExtendedCapabilities.ResourceType.size() != 0){
      scenario = '2';
      def features = capabilities.FeatureTypeList.FeatureType;
      features.each{feature ->
      if (feature.WGS84BoundingBox.size == 0){
         String[] assertParams = ['elementName', 'WGS84BoundingBox', 'scenario', scenario];
         throw new TranslatableAssertionError('TR.manual.checkContent', assertParams);
         }
      }
   }
   else if(capabilities.OperationsMetadata.ExtendedCapabilities.ExtendedCapabilities.MetadataUrl.size() != 0){
      scenario = '1';
   }
   log.info("Scenario: " + scenario);

